CREATE TABLE public.institution_additional_roles (institution_id uuid NOT NULL REFERENCES public.institutions(id), user_id uuid NOT NULL, role text NOT NULL CHECK(role IN ('ministro_carino','asesor_especialidad','director_general')), specialty text NOT NULL DEFAULT '', can_read_reports boolean NOT NULL DEFAULT false, assigned_by uuid NOT NULL, assigned_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(institution_id,user_id,role));
GRANT SELECT ON public.institution_additional_roles TO authenticated;
GRANT ALL ON public.institution_additional_roles TO service_role;
ALTER TABLE public.institution_additional_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY additional_roles_read ON public.institution_additional_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR public.institution_role_of(institution_id)::text IN ('direccion','subdireccion'));
CREATE TABLE public.institution_additional_role_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, institution_id uuid NOT NULL, user_id uuid NOT NULL, role text NOT NULL, specialty text NOT NULL, can_read_reports boolean NOT NULL, actor_id uuid NOT NULL, changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.institution_additional_role_events TO authenticated;
GRANT ALL ON public.institution_additional_role_events TO service_role;
ALTER TABLE public.institution_additional_role_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY additional_events_admin ON public.institution_additional_role_events FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.assign_additional_institution_role(_inst uuid,_email text,_role text,_specialty text,_reports boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE target uuid; BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Solo Max puede autorizar accesos adicionales'; END IF; IF _role NOT IN ('ministro_carino','asesor_especialidad','director_general') OR length(_specialty)>120 THEN RAISE EXCEPTION 'Rol inválido'; END IF; SELECT id INTO target FROM auth.users WHERE lower(email)=lower(btrim(_email)) AND email_confirmed_at IS NOT NULL; IF target IS NULL THEN RAISE EXCEPTION 'La persona debe ingresar y confirmar primero su cuenta'; END IF; IF NOT EXISTS(SELECT 1 FROM public.institution_members WHERE institution_id=_inst AND user_id=target) THEN RAISE EXCEPTION 'Asigne primero la persona a esta institución'; END IF; IF _role='ministro_carino' AND _reports THEN RAISE EXCEPTION 'El rol honorífico no consulta registros privados'; END IF; IF _role='asesor_especialidad' AND btrim(_specialty)='' THEN RAISE EXCEPTION 'Indique la especialidad'; END IF; INSERT INTO public.institution_additional_roles VALUES(_inst,target,_role,btrim(_specialty),_reports,auth.uid(),now()) ON CONFLICT(institution_id,user_id,role) DO UPDATE SET specialty=excluded.specialty,can_read_reports=excluded.can_read_reports,assigned_by=excluded.assigned_by,assigned_at=excluded.assigned_at; INSERT INTO public.institution_additional_role_events(institution_id,user_id,role,specialty,can_read_reports,actor_id) VALUES(_inst,target,_role,btrim(_specialty),_reports,auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.assign_additional_institution_role(uuid,text,text,text,boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.assign_additional_institution_role(uuid,text,text,text,boolean) TO authenticated;
CREATE FUNCTION public.additional_institution_reports(_inst uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.institution_additional_roles WHERE institution_id=_inst AND user_id=auth.uid() AND can_read_reports AND role IN ('director_general','asesor_especialidad')) AND NOT coalesce(public.has_role(auth.uid(),'admin'),false) THEN RAISE EXCEPTION 'Sin permiso'; END IF; RETURN jsonb_build_object('institution',(SELECT name FROM public.institutions WHERE id=_inst),'members',(SELECT count(*) FROM public.institution_members WHERE institution_id=_inst),'permissions',(SELECT coalesce(jsonb_agg(s),'[]'::jsonb) FROM (SELECT status,count(*) count FROM public.staff_permission_requests WHERE institution_id=_inst GROUP BY status) s),'publications',(SELECT count(*) FROM public.institution_publications p WHERE p.institution_id=_inst AND EXISTS(SELECT 1 FROM public.institution_additional_roles r WHERE r.institution_id=_inst AND r.user_id=auth.uid() AND r.can_read_reports AND (r.role='director_general' OR (r.role='asesor_especialidad' AND lower(p.subject)=lower(r.specialty)))))); END $$;
REVOKE ALL ON FUNCTION public.additional_institution_reports(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.additional_institution_reports(uuid) TO authenticated;
CREATE FUNCTION public.export_institution_backup(_inst uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT coalesce(public.has_role(auth.uid(),'admin'),false) AND NOT coalesce(public.institution_role_of(_inst)::text IN ('direccion','subdireccion'),false) THEN RAISE EXCEPTION 'Sin permiso para respaldar esta institución'; END IF; RETURN jsonb_build_object('format','practicatecnica-institution','version',1,'exported_at',now(),'institution',(SELECT jsonb_build_object('id',id,'name',name,'kind',kind) FROM public.institutions WHERE id=_inst),'users',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.user_id,'name',p.display_name,'email',u.email,'institution_role',m.member_role)),'[]'::jsonb) FROM public.institution_members m JOIN auth.users u ON u.id=m.user_id LEFT JOIN public.profiles p ON p.id=m.user_id WHERE m.institution_id=_inst),'grades',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'holder',d.holder,'title',d.title,'grades',d.grades,'issued_at',d.issued_at,'signer_name',d.signer_name,'signer_role',d.signer_role,'verification_hash',d.verification_hash)),'[]'::jsonb) FROM public.institution_signed_documents d WHERE d.institution_id=_inst AND d.kind='grades'),'permissions',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'requester_id',r.requester_id,'kind',r.kind,'starts_on',r.starts_on,'ends_on',r.ends_on,'hours',r.hours,'status',r.status,'created_at',r.created_at,'reviewed_at',r.reviewed_at,'reviewer_id',r.reviewer_id,'justified_at',r.justified_at,'verification_hash',r.verification_hash)),'[]'::jsonb) FROM public.staff_permission_requests r WHERE r.institution_id=_inst),'excluded',jsonb_build_array('passwords','sessions','medical_documents','attachment_files','clinical_details'),'compatibility','JSON portable; SEA/PIAD import not verified'); END $$;
REVOKE ALL ON FUNCTION public.export_institution_backup(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.export_institution_backup(uuid) TO authenticated;